    function maxNumberOfBalloons($text) {
        $cnt1 = $cnt2 = $cnt3 = $cnt4 = $cnt5 = 0;
        for ($i = 0; $i < strlen($text); $i++) {
            if ($text[$i] == 'b') {
                $cnt1 += 1;
            } elseif ($text[$i] == 'a') {
                $cnt2 += 1;
            } elseif ($text[$i] == 'l') {
                $cnt3 += 1;
            } elseif ($text[$i] == 'o') {
                $cnt4 += 1;
            } elseif ($text[$i] == 'n') {
                $cnt5 += 1;
            }
        }
        $cnt3 = floor($cnt3 / 2);
        $cnt4 = floor($cnt4 / 2);
        return min($cnt1, $cnt2, $cnt3, $cnt4, $cnt5);
    }
}

package io.github.leetcode.strings;

public class MaximumNumberOfBalloons {

    public int maxNumberOfBalloons(String text) {
        int n = text.length();
        int[] chars = new int[26];

        for (int i = 0; i < n; i++) {
            char c = text.charAt(i);
            chars[c - 97]++;
        }

        int count = 0;
        String balloon = "balloon";
        boolean flag = true;

        while (flag) {

            for (int i = 0; i < 7; i++) {
                char c = balloon.charAt(i);
                chars[c - 97]--;
                if (chars[c - 97] < 0) {
                    flag = false;
                    break;
                }
            }

            if (flag) count++;
        }

        return count;
    }

}

